def _project(study, S, y):
    z = np.asarray(study['Z_nuisance'])
    gram = z.T @ z + study['nuisance_ridge'] * np.eye(z.shape[1])
    values = np.column_stack((S, y))
    values -= z @ np.linalg.solve(gram, z.T @ values)
    return (values[:, :-1], values[:, -1])
